// Human-facing explanations for the configuration registry. Operational state,
// editability, defaults and restart requirements come from the API, not this copy.

import { FANSLY_PAUSE_MAX_MS, FANSLY_PAUSE_MIN_MS } from "@agency_hub_core/shared";

export interface ConfigCopy {
  /** Short Russian name, used as the primary heading. */
  title: string;
  /** One sentence explaining the purpose. */
  short: string;
  /** What changes for the user, with relevant limits and dependencies. */
  long: string;
  /** Unit of the raw input value; display only, without conversion. */
  unit?: string;
  /** Plain-language explanation of the registry's cost or data warning. */
  warning?: string;
}

function copy(title: string, short: string, long: string, detail: Pick<ConfigCopy, "unit" | "warning"> = {}): ConfigCopy {
  return { title, short, long, ...detail };
}

/** The legacy endpoint pauses (plan §2.3): kept readable until the key is
 *  removed, but they no longer apply to anything. */
function endpointPauseRetired(title: string, what: string): ConfigCopy {
  return copy(title, `Больше не применяется: отдельной паузы для ${what} Fansly нет.`,
    "Все запросы страницы Fansly разделяет одна «Пауза между запросами Fansly» со случайной надбавкой 0–20 %. Значение из окружения сервера ещё читается, но ни на что не влияет; при запуске сервер пишет предупреждение. Настройка будет удалена вместе со старым движком синхронизации.",
    { unit: "мс" });
}

/** Keys retired with a legacy Fansly component (step 4): still readable until
 *  the key is removed (S4-26), but nothing reads them any more. */
function retiredWithLegacyFansly(title: string, reason: string): ConfigCopy {
  return copy(title, `Больше не действует: ${reason}.`,
    "Hub больше ничего по этой настройке не делает. Сохранённое значение ни на что не влияет; настройка будет удалена вместе с остальными настройками старого движка синхронизации Fansly.");
}

/** The legacy Fansly content lanes' switches, page lists and limits (step 4):
 *  kept readable until the key is removed, but they no longer apply to anything. */
function contentLaneRetired(title: string, what: string, unit?: string): ConfigCopy {
  return copy(`${title} (больше не действует)`, `Больше не применяется: ${what} Fansly читает новый движок синхронизации.`,
    "Статистику, уведомления, каталог, комментарии, выводы, статистику материалов и реакции на посты новый движок синхронизации Fansly читает по своему реестру; отдельных переключателей, списков страниц и дневных лимитов у него нет. Значение ещё читается, но ни на что не влияет. Настройка будет удалена вместе со старым движком синхронизации.",
    unit === undefined ? {} : { unit });
}

